      trelloApiKey: 'key',
      trelloToken: 'token',
      idList: 'list-456',
      idChecklist: 'checklist-999',
      fetch,
    };

    const payload: CalWebhookPayload = {
      triggerEvent: 'BOOKING_CREATED',
      payload: {
        attendees: [{ email: 'john.doe@example.com', name: 'John Doe' }],
      },
    };

    const result = await handle(payload, config);
    expect(result.cardId).toBe('card-123');
    expect(result.cardName).toBe('Target Card');
    expect(result.checklistItemId).toBe('item-789');
